```fl
// ============================================================================
// FreeLang Transaction 모듈 - 스냅샷 기반 트랜잭션 관리
// ============================================================================
// 목표: schema.fl 테이블에 BEGIN/COMMIT/ROLLBACK 트랜잭션 지원
// 원리:
//   1. TxEntry: 각 변경 전 스냅샷 (이전 int/str/bool 값 저장)
//   2. tx_insert: 삽입 후 row_id 기록 (롤백 시 소프트 삭제)
//   3. tx_update: 이전 값 스냅샷 저장 후 업데이트
//   4. tx_delete: 소프트 삭제 (롤백 시 복구)
//   5. tx_rollback: TxEntry 역순으로 복구
// 구조:
//   - 상수 (상태, 연산 타입)
//   - TxEntry, Transaction 구조체
//   - 트랜잭션 CRUD
//   - commit/rollback
// ============================================================================

module transaction {
    // === 트랜잭션 상태 ===
    const TX_ACTIVE:      i32 = 0;
    const TX_COMMITTED:   i32 = 1;
    const TX_ROLLED_BACK: i32 = 2;

    // === 연산 타입 ===
    const TX_OP_INSERT: i32 = 1;
    const TX_OP_UPDATE_INT:  i32 = 2;
    const TX_OP_UPDATE_STR:  i32 = 3;
    const TX_OP_UPDATE_BOOL: i32 = 4;
    const TX_OP_DELETE: i32 = 5;

    // === 에러 코드 ===
    const TX_OK:            i32 = 0;
    const TX_ERR_NOT_ACTIVE: i32 = 40;
    const TX_ERR_FULL:      i32 = 41;
    const TX_ERR_NOTFOUND:  i32 = 42;

    // === 제한값 ===
    const MAX_TX_ENTRIES: i32 = 256;

    // === 데이터 구조체 ===

    // 트랜잭션 엔트리 (롤백용 스냅샷)
    struct TxEntry {
        op:        i32;     // TX_OP_*
        row_id:    i64;
        col_idx:   i32;     // UPDATE 시 컬럼 인덱스
        old_int:   i64;     // UPDATE_INT 이전 값
        old_str:   string;  // UPDATE_STR 이전 값
        old_bool:  bool;    // UPDATE_BOOL 이전 값
    }

    // 트랜잭션
    struct Transaction {
        id:          i64;
        state:       i32;   // TX_ACTIVE / TX_COMMITTED / TX_ROLLED_BACK
        entries:     [TxEntry];
        entry_count: i32;
    }

    // 전역 트랜잭션 ID 카운터
    let g_next_tx_id: i64 = 1;

    // === 팩토리 함수 ===

    func tx_begin() -> Transaction {
        let tx_id = g_next_tx_id;
        g_next_tx_id = g_next_tx_id + 1;
        return Transaction{
            id:          tx_id,
            state:       TX_ACTIVE,
            entries:     make([TxEntry], MAX_TX_ENTRIES),
            entry_count: 0,
        };
    }

    // === 트랜잭션 CRUD (테이블 직접 참조) ===

    // INSERT (TxEntry에 row_id 기록)
    func tx_insert(tx: *Transaction, t: *schema.Table, row: schema.RecordRow) -> (i64, i32) {
        if tx.state != TX_ACTIVE {
            return (0, TX_ERR_NOT_ACTIVE);
        }
        if tx.entry_count >= MAX_TX_ENTRIES {
            return (0, TX_ERR_FULL);
        }

        let row_id, ok = t.table_insert(row);
        if !ok {
            return (0, TX_ERR_FULL);
        }

        tx.entries[tx.entry_count] = TxEntry{
            op:       TX_OP_INSERT,
            row_id:   row_id,
            col_idx:  -1,
            old_int:  0,
            old_str:  "",
            old_bool: false,
        };
        tx.entry_count = tx.entry_count + 1;

        return (row_id, TX_OK);
    }

    // UPDATE INT (이전 값 스냅샷)
    func tx_update_int(tx: *Transaction, t: *schema.Table, row_id: i64, col_idx: i32, new_val: i64) -> i32 {
        if tx.state != TX_ACTIVE {
            return TX_ERR_NOT_ACTIVE;
        }
        if tx.entry_count >= MAX_TX_ENTRIES {
            return TX_ERR_FULL;
        }

        // 이전 값 조회
        let row, found = t.table_get(row_id);
        if !found {
            return TX_ERR_NOTFOUND;
        }

        // 타입 내 인덱스 계산
        let type_idx = t.schema.col_type_idx(col_idx);
        let old_val = row.int_vals[type_idx];

        // 스냅샷 저장
        tx.entries[tx.entry_count] = TxEntry{
            op:       TX_OP_UPDATE_INT,
            row_id:   row_id,
            col_idx:  col_idx,
            old_int:  old_val,
            old_str:  "",
            old_bool: false,
        };
        tx.entry_count = tx.entry_count + 1;

        // 실제 업데이트
        t.table_update_int(row_id, col_idx, new_val);
        return TX_OK;
    }

    // UPDATE STR (이전 값 스냅샷)
    func tx_update_str(tx: *Transaction, t: *schema.Table, row_id: i64, col_idx: i32, new_val: string) -> i32 {
        if tx.state != TX_ACTIVE {
            return TX_ERR_NOT_ACTIVE;
        }
        if tx.entry_count >= MAX_TX_ENTRIES {
            return TX_ERR_FULL;
        }

        let row, found = t.table_get(row_id);
        if !found {
            return TX_ERR_NOTFOUND;
        }

        let type_idx = t.schema.col_type_idx(col_idx);
        let old_val = row.str_vals[type_idx];

        tx.entries[tx.entry_count] = TxEntry{
            op:       TX_OP_UPDATE_STR,
            row_id:   row_id,
            col_idx:  col_idx,
            old_int:  0,
            old_str:  old_val,
            old_bool: false,
        };
        tx.entry_count = tx.entry_count + 1;

        t.table_update_str(row_id, col_idx, new_val);
        return TX_OK;
    }

    // UPDATE BOOL (이전 값 스냅샷)
    func tx_update_bool(tx: *Transaction, t: *schema.Table, row_id: i64, col_idx: i32, new_val: bool) -> i32 {
        if tx.state != TX_ACTIVE {
            return TX_ERR_NOT_ACTIVE;
        }
        if tx.entry_count >= MAX_TX_ENTRIES {
            return TX_ERR_FULL;
        }

        let row, found = t.table_get(row_id);
        if !found {
            return TX_ERR_NOTFOUND;
        }

        let type_idx = t.schema.col_type_idx(col_idx);
        let old_val = row.bool_vals[type_idx];

        tx.entries[tx.entry_count] = TxEntry{
            op:       TX_OP_UPDATE_BOOL,
            row_id:   row_id,
            col_idx:  col_idx,
            old_int:  0,
            old_str:  "",
            old_bool: old_val,
        };
        tx.entry_count = tx.entry_count + 1;

        t.table_update_bool(row_id, col_idx, new_val);
        return TX_OK;
    }

    // DELETE (소프트 삭제, 롤백 가능)
    func tx_delete(tx: *Transaction, t: *schema.Table, row_id: i64) -> i32 {
        if tx.state != TX_ACTIVE {
            return TX_ERR_NOT_ACTIVE;
        }
        if tx.entry_count >= MAX_TX_ENTRIES {
            return TX_ERR_FULL;
        }

        let row, found = t.table_get(row_id);
        if !found {
            return TX_ERR_NOTFOUND;
        }

        tx.entries[tx.entry_count] = TxEntry{
            op:       TX_OP_DELETE,
            row_id:   row_id,
            col_idx:  -1,
            old_int:  0,
            old_str:  "",
            old_bool: false,
        };
        tx.entry_count = tx.entry_count + 1;

        t.table_delete(row_id);
        return TX_OK;
    }

    // === COMMIT ===
    func tx_commit(tx: *Transaction) -> bool {
        if tx.state != TX_ACTIVE {
            return false;
        }
        tx.state = TX_COMMITTED;
        return true;
    }

    // === ROLLBACK ===
    func tx_rollback(tx: *Transaction, t: *schema.Table) -> bool {
        if tx.state != TX_ACTIVE {
            return false;
        }

        // 역순으로 복구
        let i = tx.entry_count - 1;
        for i >= 0 {
            let entry = tx.entries[i];

            if entry.op == TX_OP_INSERT {
                // 삽입 롤백: 소프트 삭제
                t.table_delete(entry.row_id);

            } else if entry.op == TX_OP_UPDATE_INT {
                // UPDATE_INT 롤백: 이전 값 복원
                t.table_update_int(entry.row_id, entry.col_idx, entry.old_int);

            } else if entry.op == TX_OP_UPDATE_STR {
                // UPDATE_STR 롤백: 이전 값 복원
                t.table_update_str(entry.row_id, entry.col_idx, entry.old_str);

            } else if entry.op == TX_OP_UPDATE_BOOL {
                // UPDATE_BOOL 롤백: 이전 값 복원
                t.table_update_bool(entry.row_id, entry.col_idx, entry.old_bool);

            } else if entry.op == TX_OP_DELETE {
                // DELETE 롤백: 소프트 삭제 해제
                // 삭제 플래그를 직접 접근 (row_id → row_idx)
                let row_idx, found = t.find_row_idx_deleted(entry.row_id);
                if found {
                    t.deleted_flags[row_idx] = false;
                }
            }

            i = i - 1;
        }

        tx.state = TX_ROLLED_BACK;
        return true;
    }

    // === 상태 확인 ===

    @inline
    func tx_is_active(tx: Transaction) -> bool {
        return tx.state == TX_ACTIVE;
    }

    @inline
    func tx_is_committed(tx: Transaction) -> bool {
        return tx.state == TX_COMMITTED;
    }

    @inline
    func tx_is_rolled_back(tx: Transaction) -> bool {
        return tx.state == TX_ROLLED_BACK;
    }

    // 트랜잭션 통계
    func tx_stats(tx: Transaction) -> string {
        let state_str = if tx.state == TX_ACTIVE {
            "ACTIVE"
        } else if tx.state == TX_COMMITTED {
            "COMMITTED"
        } else {
            "ROLLED_BACK"
        };
        let msg = "[Tx " + i64_to_str(tx.id) + "] state=" + state_str +
                  " entries=" + i32_to_str(tx.entry_count);
        return msg;
    }

    // === 헬퍼 함수 ===

    @inline
    func i32_to_str(n: i32) -> string {
        if n == 0 { return "0"; }
        if n == 1 { return "1"; }
        if n == 2 { return "2"; }
        if n == 3 { return "3"; }
        if n == 4 { return "4"; }
        if n == 5 { return "5"; }
        if n == 6 { return "6"; }
        if n == 7 { return "7"; }
        if n == 8 { return "8"; }
        if n == 9 { return "9"; }
        if n < 0 { return "-" + i32_to_str(-n); }
        let d = n / 10;
        let r = n % 10;
        return i32_to_str(d) + i32_to_str(r);
    }

    @inline
    func i64_to_str(n: i64) -> string {
        if n == 0 { return "0"; }
        if n < 0 { return "-" + i64_to_str(-n); }
        return i32_to_str(i32(n));
    }
}

// === 사용 시나리오 (주석) ===
//
// 기본 사용:
//   let tx = transaction.tx_begin();
//
//   let row = schema.record_new();
//   row.int_vals[0] = 42;
//   let id, err = transaction.tx_insert(&tx, &t, row);
//
//   let err2 = transaction.tx_update_int(&tx, &t, id, 0, 100);
//
//   transaction.tx_commit(&tx);
//
// 롤백:
//   let tx2 = transaction.tx_begin();
//   let id2, _ = transaction.tx_insert(&tx2, &t, row);
//   transaction.tx_rollback(&tx2, &t);
//   // id2는 이제 소프트 삭제된 상태
//
```

이 내용을 그대로 `/data/data/com.termux/files/home/freelang-zero-copy-db/stdlib/transaction.fl` 파일로 Write 도구를 사용해 작성해주세요. transaction.fl에 필요한 `find_row_idx_deleted` 함수는 schema.fl에 없으므로 해당 부분을 다음 코드로 대체해주세요:

```
// DELETE 롤백: 소프트 삭제 해제
// 삭제된 행을 포함해서 row_id로 탐색
let j = 0;
for j = 0; j < t.row_count; j = j + 1 {
    if t.row_ids[j] == entry.row_id {
        t.deleted_flags[j] = false;
        break;
    }
}
```

즉 `tx_rollback` 함수의 TX_OP_DELETE 처리 부분을 위와 같이 교체해주세요.

